#' Lollipop Chart (Core, Python)
#'
#' 
#' @param data .
#' @param dep .
#' @param group .
#' @param aggregation .
#' @param sortBy .
#' @param orientation .
#' @param baseline .
#' @param showMean .
#' @param showValues .
#' @param showPlot .
#' @param showPoints .
#' @param showCases .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$missing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptives} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$points} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$lollipopPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pylollipop <- function(
    data,
    dep = NULL,
    group = NULL,
    aggregation = "mean",
    sortBy = "original",
    orientation = "vertical",
    baseline = 0,
    showMean = FALSE,
    showValues = FALSE,
    showPlot = TRUE,
    showPoints = TRUE,
    showCases = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pylollipop requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pylollipopOptions$new(
        dep = dep,
        group = group,
        aggregation = aggregation,
        sortBy = sortBy,
        orientation = orientation,
        baseline = baseline,
        showMean = showMean,
        showValues = showValues,
        showPlot = showPlot,
        showPoints = showPoints,
        showCases = showCases,
        showConsole = showConsole)

    analysis <- pylollipopClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

